import { FluxType } from "./FluxType";
import { ITransactionProduct } from "./ITransactionProduct";


export class TransactionProduct extends FluxType implements ITransactionProduct {

    public getDispName(): string {
        return this.productUniqueId || `Transaction Product ${this.id}`
    }

    public obName: string = "TransactionProduct";
    
    public serialize() {
        return {
            uniqueId: this.uniqueId,
            id: this.id,
            metadata: this.metadata,
            productId: this.productId,
            productVersion: this.productVersion,
            productDumpId: this.productDumpId,
            productUniqueId: this.productUniqueId,
            transactionId: this.transactionId,
            transactionUniqueId: this.transactionUniqueId,
            quantity: this.quantity,
            backOrdered: this.backOrdered,
            objectType: "transaction_product"
        }
    }
    
    uniqueId: string;
    id: number;
    metadata: string;
    productId: number;
    productVersion: number;
    productDumpId: number;
    productUniqueId: string;
    transactionId: number;
    transactionUniqueId: string;
    quantity: number;
    backOrdered: boolean;
    protected objectType: string = "transaction_product";

    constructor(transactionProduct?: Partial<ITransactionProduct>) {
        super(transactionProduct, TransactionProduct)
        Object.assign(this, transactionProduct);
    }

    public static async createInstanceLazy(tp: Partial<ITransactionProduct>) {
        return await FluxType.instantiateLazyInstance(tp, this)
    }

    public static async createInstanceSafe(tp: Partial<ITransactionProduct>) {
        return await FluxType.instantiateInstance(tp, this)
    }
}

