import { PaymentLinkQuery } from './PaymentLinkQuery';
import { IReusableLink } from './IReusableLink';

export class ReusableLinkQuery extends PaymentLinkQuery {
    public obName: string = "ReusableLinkQuery";

    public constructor(query?: Partial<ReusableLinkQuery>) {
        super(query);
        // Default to filtering for reusable links only
        this.isReusable = true;
        Object.assign(this, query);
    }

    public serialize() {
        return {
            ...super.serialize(),
            isReusable: this.isReusable
        };
    }
}

